<script setup>
import {ref,computed,onMounted,onBeforeUnmount,defineAsyncComponent} from 'vue'
import {MessageCircle,Send,RefreshCw,Settings2,ArrowLeft} from 'lucide-vue-next'
import {voiceApi,stamp} from '../voice/operations'
const SocialLeadsPanel=defineAsyncComponent(()=>import('./SocialLeadsPanel.vue'))
const leadPanel=ref(null)
const state=ref(null),detail=ref(null),error=ref(''),notice=ref(''),busy=ref(false),search=ref(''),status=ref('open'),page=ref(1),messagePage=ref(1),body=ref(''),template=ref(''),experimental=ref(false),settings=ref(false),route=ref({sender_id:'',queue_id:'',enabled:false,max_open:5}),assignee=ref(''),queue=ref('')
let timer=null,polling=false,sendKey=null,disposed=false
const messages=computed(()=>[...(detail.value?.messages.data||[])].reverse())
const canReply=computed(()=>detail.value?.conversation.assigned_user_id===state.value?.user_id&&detail.value?.conversation.status==='open')
const sender=id=>state.value?.senders.find(s=>s.id===id)
const person=id=>state.value?.agents.find(s=>s.id===id)?.name||'Sem responsável'
const labels={received:'Recebida',sending:'Enviando',accepted:'Aceita',queued:'Na fila',sent:'Enviada',delivered:'Entregue',read:'Lida',unknown:'Sem confirmação',failed:'Falhou',undelivered:'Não entregue',cancelled:'Cancelada'}
async function api(path='',method='GET',d){return voiceApi('/conversations'+path,method,d)}
async function load(){state.value=await api('?'+new URLSearchParams({status:status.value,search:search.value,page:page.value}))}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function open(c){detail.value=await api('/'+c.id+'?page='+messagePage.value);assignee.value=detail.value.conversation.assigned_user_id||'';queue.value=detail.value.conversation.queue_id||''}
async function select(c){if(body.value||template.value){notice.value='Envie ou limpe o rascunho antes de abrir outra conversa.';return}messagePage.value=1;await open(c);await api('/'+c.id+'/read','POST',{})}
async function assign(mine=false,nextStatus=null){const c=detail.value.conversation;await api('/'+c.id+'/assign','POST',{user_id:mine?state.value.user_id:(assignee.value||null),queue_id:queue.value||null,revision:c.revision,status:nextStatus||c.status});await open(c);await load()}
async function send(){const c=detail.value.conversation;sendKey ||= crypto.randomUUID();const d={idempotency_key:sendKey,body:template.value?null:body.value,qr_template_id:template.value||null,experimental_confirmed:experimental.value};const result=await api('/'+c.id+'/send','POST',d);sendKey=null;body.value='';template.value='';experimental.value=false;await open(c);await load();notice.value=result.status==='unknown'?'Envio sem confirmação. Consulte o histórico antes de tentar novamente.':'Mensagem registrada: '+(labels[result.status]||result.status)}
async function tick(){if(busy.value||polling||disposed)return;polling=true;try{await load();if(detail.value){const id=detail.value.conversation.id;const fresh=await api('/'+id+'?page='+messagePage.value);if(detail.value?.conversation.id===id)detail.value=fresh}}catch(e){error.value=e.message}finally{polling=false}}
onMounted(()=>{run(load);timer=setInterval(tick,15000)});onBeforeUnmount(()=>{disposed=true;clearInterval(timer)})
defineExpose({requestLeave:fn=>{if(body.value||template.value){notice.value='Envie ou limpe o rascunho antes de sair.';return}if(leadPanel.value)leadPanel.value.requestLeave(fn);else fn()}})
</script>
<template><div class="inbox">
 <div class="heading"><div><span class="eyebrow">CONVERSAS QUE CONTINUAM</span><h1>Caixa de atendimento</h1><p>WhatsApp, responsáveis e origem dos leads no mesmo lugar.</p></div><div class="actions"><button v-if="state?.can_manage" class="secondary" @click="settings=!settings"><Settings2 :size="16"/>Distribuição</button><button class="secondary" @click="run(async()=>{await load();if(detail)await open(detail.conversation)})"><RefreshCw :size="16"/>Atualizar</button></div></div>
 <p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="notice" role="status">{{notice}}</p>
 <div v-if="settings&&state?.can_manage" class="table-card box"><h3>Distribuição automática por remetente</h3><form @submit.prevent="run(async()=>{await api('/routes','POST',route);await load();notice='Distribuição salva para as próximas entradas.'})"><div class="grid"><label>Remetente<select v-model.number="route.sender_id" required><option value="">Selecione</option><option v-for="s in state.senders" :value="s.id">{{s.label}} · {{s.number}}</option></select></label><label>Fila<select v-model.number="route.queue_id" required><option value="">Selecione</option><option v-for="q in state.queues" :value="q.id">{{q.name}}</option></select></label><label>Conversas abertas por atendente<input type="number" v-model.number="route.max_open" min="1" max="20"></label></div><label class="check-label"><input type="checkbox" v-model="route.enabled">Distribuir entre atendentes disponíveis, priorizando quem tem menos conversas abertas</label><button class="primary" :disabled="busy">Salvar distribuição</button></form><p v-for="r in state.routes">{{sender(r.sender_id)?.number}} · {{r.enabled?'Ativa':'Pausada'}} · até {{r.max_open}} conversas <button class="secondary" @click="route={...r,enabled:!!r.enabled}">Editar</button></p></div>
 <div class="inbox-layout" :class="{selected:detail}">
  <aside class="table-card threads"><form class="filters" @submit.prevent="run(async()=>{page=1;await load()})"><input v-model="search" placeholder="Buscar telefone" aria-label="Buscar telefone"><select v-model="status" @change="page=1;run(load)"><option value="open">Abertas</option><option value="closed">Concluídas</option></select><button class="secondary">Buscar</button></form><button v-for="c in state?.rows.data" :key="c.id" :class="['thread',{active:detail?.conversation.id===c.id}]" @click="run(()=>select(c))"><strong>{{c.phone}} <span v-if="c.last_inbound_at&&(!c.read_at||c.last_inbound_at>c.read_at)" class="dot"/></strong><small>{{sender(c.sender_id)?.label}} · {{sender(c.sender_id)?.provider==='qr'?'QR':'API'}}</small><small>{{person(c.assigned_user_id)}}</small><small>{{stamp(c.last_message_at)}}</small></button><p v-if="!state?.rows.data.length" class="empty">Nenhuma conversa neste filtro.</p><div class="actions pager"><button class="secondary" :disabled="page===1" @click="page--;run(load)">Anterior</button><span>{{page}} / {{state?.rows.last_page||1}}</span><button class="secondary" :disabled="page>=(state?.rows.last_page||1)" @click="page++;run(load)">Próxima</button></div></aside>
  <article class="table-card conversation"><template v-if="detail"><header><button class="secondary mobile-back" @click="detail=null"><ArrowLeft :size="16"/>Conversas</button><h2>{{detail.contact?.name||detail.conversation.phone}}</h2><p>{{detail.conversation.phone}} · de {{sender(detail.conversation.sender_id)?.number}} · {{person(detail.conversation.assigned_user_id)}}</p><p v-if="detail.contact?.suppressed_at" class="error">Contato pediu interrupção. Envios bloqueados.</p><div class="actions"><button v-if="!detail.conversation.assigned_user_id||state.can_manage" class="secondary" @click="run(()=>assign(true))">Assumir conversa</button><button v-if="canReply||state.can_manage" class="secondary" @click="run(()=>assign(false,detail.conversation.status==='open'?'closed':'open'))">{{detail.conversation.status==='open'?'Concluir conversa':'Reabrir conversa'}}</button></div><details v-if="state.can_manage"><summary>Responsável e fila</summary><div class="grid"><label>Fila<select v-model.number="queue"><option value="">Sem fila</option><option v-for="q in state.queues" :value="q.id">{{q.name}}</option></select></label><label>Atendente<select v-model.number="assignee"><option value="">Sem responsável</option><option v-for="a in state.agents" :value="a.id">{{a.name}}</option></select></label></div><button class="secondary" @click="run(()=>assign())">Salvar responsável</button></details><details v-if="detail.conversation.attribution"><summary>Origem do contato</summary><pre>{{JSON.parse(detail.conversation.attribution)}}</pre></details></header><div class="messages"><div class="actions pager" v-if="detail.messages.last_page>1"><button class="secondary" :disabled="messagePage>=detail.messages.last_page" @click="messagePage++;run(()=>open(detail.conversation))">Mais antigas</button><button class="secondary" :disabled="messagePage<=1" @click="messagePage--;run(()=>open(detail.conversation))">Mais recentes</button></div><div v-for="m in messages" :key="m.id" :class="['bubble',m.direction]"><p>{{m.body||'Mensagem de template ou conteúdo não textual'}}</p><div v-if="m.interactive"><span v-for="b in JSON.parse(m.interactive).buttons||[]" :key="b.id" class="button-preview">{{b.label}}</span></div><strong v-if="m.button_id" class="chosen">Botão: {{m.button_label}} · {{m.button_id}}</strong><small>{{stamp(m.created_at)}} · {{labels[m.status]||m.status}}</small></div></div><form v-if="canReply" class="composer" @submit.prevent="run(send)"><label v-if="sender(detail.conversation.sender_id)?.provider==='qr'">Template com botões<select v-model="template" @change="sendKey=null"><option value="">Texto livre</option><option v-for="t in state.templates" :value="t.id">{{t.name}} · experimental</option></select></label><textarea v-if="!template" v-model="body" @input="sendKey=null" required maxlength="4000" placeholder="Escreva uma resposta…" aria-label="Resposta"/><template v-else><p>{{state.templates.find(t=>t.id===template)?.body}}</p><label class="check-label"><input type="checkbox" v-model="experimental" required>Confirmo o envio experimental dos botões por QR</label></template><div class="actions"><button class="primary" :disabled="busy||(!body&&!template)"><Send :size="16"/>Enviar resposta</button><button type="button" class="secondary" @click="body='';template='';sendKey=null">Limpar rascunho</button></div><small>Envio manual após mensagem recebida nas últimas 24 horas. Responder aqui não reinicia a cadência.</small></form><p v-else class="empty">Assuma a conversa aberta para responder.</p></template><div v-else class="placeholder"><MessageCircle :size="48"/><h2>Selecione uma conversa</h2><p>Veja mensagens, entregas e opções escolhidas pelo cliente.</p></div></article>
 </div>
 <SocialLeadsPanel v-if="state?.can_manage" ref="leadPanel"/>
</div></template>
<style scoped>
.heading,.actions{display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap}.actions{justify-content:flex-start}.heading p,.inbox small,.inbox p{color:#75806b;line-height:1.7}.inbox-layout{display:grid;grid-template-columns:320px minmax(0,1fr);gap:20px;align-items:start}.threads{overflow:hidden}.filters{padding:16px;display:flex;gap:8px;flex-wrap:wrap}.filters input{width:100%}.thread{display:flex;flex-direction:column;gap:5px;text-align:left;width:100%;padding:18px 20px;border-top:1px solid #eee}.thread.active{background:#f6edda;border-left:3px solid #bf953c}.thread small{font-size:11px}.conversation{overflow:hidden;min-height:600px}.conversation header{padding:24px;border-bottom:1px solid #e2e6db}.conversation h2{margin:0;font-size:20px}.messages{padding:24px;max-height:560px;overflow:auto;background:#f2f4ed;display:flex;flex-direction:column;gap:14px}.bubble{max-width:85%;background:white;border:1px solid #e0e4d7;border-radius:14px;padding:14px 18px;align-self:flex-start}.bubble.outbound{align-self:flex-end;background:#e5eedc}.bubble p{white-space:pre-wrap;margin:0 0 8px;color:#303a29}.bubble small{font-size:10px}.button-preview{display:block;text-align:center;background:#ffffffa0;border:1px solid #d6dfca;padding:7px;border-radius:6px;margin:4px 0}.chosen{display:block;font-size:12px;margin:8px 0;color:#527238}.composer{padding:22px;border-top:1px solid #e2e6db}.composer textarea{min-height:90px;margin-bottom:14px}.composer small{display:block;margin-top:10px}.placeholder{display:flex;flex-direction:column;align-items:center;justify-content:center;padding:140px 30px;text-align:center;color:#c0983e}.placeholder h2{margin-top:20px}.box{padding:24px;margin:20px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:16px}.inbox label:not(.check-label){display:flex;flex-direction:column;gap:8px;font-size:12px;margin:12px 0}.inbox select{padding:10px;border:1px solid #daddd2;background:white;border-radius:10px;max-width:100%}.empty{padding:25px}.pager{padding:14px;font-size:12px}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:#c39938}.notice{padding:14px;background:#faf0d4;border-radius:10px}.inbox pre{white-space:pre-wrap;word-break:break-word;font-size:12px}.scroll{overflow:auto}.mobile-back{display:none}@media(max-width:900px){.inbox-layout{grid-template-columns:260px minmax(0,1fr)}}@media(max-width:680px){.inbox-layout{grid-template-columns:1fr}.inbox-layout.selected .threads{display:none}.inbox-layout:not(.selected) .conversation{display:none}.mobile-back{display:inline-flex;margin-bottom:15px}.messages{padding:15px}.bubble{max-width:95%}}
</style>
